mapper.select:
SELECT n.id, n.user_id AS userId, receiver.username AS receiverUsername, receiver.avatar AS receiverAvatar, n.sender_id AS senderId, sender.username AS senderUsername, sender.avatar AS senderAvatar, n.type, n.title, n.content, n.target_type AS targetType, n.target_id AS targetId, CASE WHEN n.target_type = 'NOTE' THEN target_note.title WHEN n.target_type = 'COMMENT' THEN target_comment.content WHEN n.target_type = 'USER' THEN target_user.username ELSE NULL END AS targetTitle, n.is_read AS isRead, n.is_deleted AS isDeleted, n.created_at AS createdAt FROM t_notification n LEFT JOIN t_user receiver ON n.user_id = receiver.id LEFT JOIN t_user sender ON n.sender_id = sender.id LEFT JOIN t_note_item target_note ON n.target_type = 'NOTE' AND n.target_id = target_note.id LEFT JOIN t_comment target_comment ON n.target_type = 'COMMENT' AND n.target_id = target_comment.id LEFT JOIN t_user target_user ON n.target_type = 'USER' AND n.target_id = target_user.id
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR n.content LIKE CONCAT('%', #{keyword}, '%') OR receiver.username LIKE CONCAT('%', #{keyword}, '%') OR sender.username LIKE CONCAT('%', #{keyword}, '%') OR target_note.title LIKE CONCAT('%', #{keyword}, '%') OR target_comment.content LIKE CONCAT('%', #{keyword}, '%'))
AND n.user_id = #{userId}
AND n.type = #{type}
AND n.is_read = #{isRead}
AND n.is_deleted = #{isDeleted}
AND n.created_at >= #{startTime}
AND n.created_at <= #{endTime}
ORDER BY n.created_at DESC, n.id DESC
